import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';

const CameraRecognition = () => {
  const COLORS = {
    primary: '#4F46E5',
    success: '#10B981',
    danger: '#EF4444',
    warning: '#F59E0B',
    textMain: '#1E293B',
    textMuted: '#64748B',
    border: '#E2E8F0',
    surface: '#FFFFFF'
  };

  const webcamRef = useRef(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(false);

  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) return;

    setLoading(true);
    setError(null);

    try {
      const imageSrc = webcamRef.current.getScreenshot();

      if (!imageSrc) {
        throw new Error("Impossible de capturer l'image");
      }

      const response = await attendanceAPI.recognize(imageSrc);

      // ✅ NORMALISATION ULTRA SAFE
      let data = null;

      if (response && typeof response === "object") {
        if (response.data && typeof response.data === "object") {
          data = response.data;
        } else {
          data = response;
        }
      }

      console.log("API RAW RESPONSE:", response);
      console.log("DATA:", data);

      if (!data || typeof data !== "object") {
        throw new Error("Réponse API invalide");
      }

      // ❌ Gestion cas "unknown face"
      if (data.success === false) {
        throw new Error(data.message || "Visage non reconnu");
      }

      // ✅ PROTECTION ANTI-OBJET REACT
      const safeString = (val) => {
        if (typeof val === "string" || typeof val === "number") {
          return String(val);
        }
        return "N/A";
      };

      const safeResult = {
        name: safeString(data.student || data.student_name || "Inconnu"),
        studentId: safeString(data.student_id),
        attendanceId: safeString(data.attendance_id),
        confidence: (Number(data.confidence ?? 0) * 100).toFixed(1),
        timestamp: safeString(data.timestamp || new Date().toLocaleTimeString())
      };

      setResult(safeResult);

    } catch (err) {
      console.error("ERROR:", err);

      const msg =
        err?.response?.data?.error ||
        err?.response?.data?.message ||
        err?.message ||
        "Erreur de connexion";

      setError(String(msg));
      setResult(null);
    } finally {
      setLoading(false);
    }
  }, []);

  // AUTO MODE
  useEffect(() => {
    let interval;
    if (autoMode && !loading) {
      interval = setInterval(handleCapture, 5000);
    }
    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  const styles = {
    container: { padding: '20px', maxWidth: '600px', margin: '0 auto' },
    card: {
      backgroundColor: COLORS.surface,
      borderRadius: '16px',
      padding: '25px',
      boxShadow: '0 4px 20px rgba(0,0,0,0.08)',
      border: `1px solid ${COLORS.border}`
    },
    title: {
      margin: '0 0 20px 0',
      fontSize: '1.4rem',
      fontWeight: 800,
      color: COLORS.textMain,
      textAlign: 'center'
    },
    cameraWrapper: {
      position: 'relative',
      borderRadius: '12px',
      overflow: 'hidden',
      backgroundColor: '#000'
    },
    webcam: { width: '100%' },
    loaderOverlay: {
      position: 'absolute',
      inset: 0,
      backgroundColor: 'rgba(0,0,0,0.6)',
      color: '#fff',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontWeight: 'bold'
    },
    buttonGroup: { display: 'flex', gap: '10px', marginTop: '20px' },
    btn: {
      flex: 1,
      padding: '12px',
      border: 'none',
      borderRadius: '10px',
      color: '#fff',
      fontWeight: 'bold',
      fontSize: '14px'
    },
    resultArea: { marginTop: '20px', minHeight: '100px' },
    successBox: {
      padding: '15px',
      backgroundColor: '#DCFCE7',
      color: '#166534',
      borderRadius: '10px'
    },
    successBoxName: {
      fontSize: '1.2rem',
      fontWeight: 'bold',
      marginBottom: '8px'
    },
    row: {
      display: 'flex',
      justifyContent: 'space-between',
      fontSize: '0.9rem'
    },
    errorBox: {
      padding: '15px',
      backgroundColor: '#FEE2E2',
      color: '#991B1B',
      borderRadius: '10px'
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>📷 Reconnaissance Faciale</h2>

        <div style={styles.cameraWrapper}>
          <Webcam
            ref={webcamRef}
            audio={false}
            screenshotFormat="image/jpeg"
            videoConstraints={videoConstraints}
            style={styles.webcam}
          />
          {loading && <div style={styles.loaderOverlay}>⏳ Analyse...</div>}
        </div>

        <div style={styles.buttonGroup}>
          <button
            onClick={handleCapture}
            disabled={loading || autoMode}
            style={{
              ...styles.btn,
              backgroundColor: COLORS.primary,
              opacity: loading || autoMode ? 0.6 : 1
            }}
          >
            🔍 Scan
          </button>

          <button
            onClick={() => setAutoMode(!autoMode)}
            style={{
              ...styles.btn,
              backgroundColor: autoMode ? COLORS.danger : COLORS.success
            }}
          >
            {autoMode ? 'STOP' : 'AUTO'}
          </button>
        </div>

        <div style={styles.resultArea}>
          {result && (
            <div style={styles.successBox}>
              <div style={styles.successBoxName}>✅ {result.name}</div>
              <div style={styles.row}><span>ID:</span><span>{result.studentId}</span></div>
              <div style={styles.row}><span>Présence:</span><span>{result.attendanceId}</span></div>
              <div style={styles.row}>
                <span>Confiance:</span>
                <span style={{
                  color: parseFloat(result.confidence) > 80 ? COLORS.success : COLORS.warning
                }}>
                  {result.confidence}%
                </span>
              </div>
              <div style={{ marginTop: 8 }}>🕐 {result.timestamp}</div>
            </div>
          )}

          {error && (
            <div style={styles.errorBox}>
              ❌ {error}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CameraRecognition;
